const defaults={duration:440,bounce:1.38,stretch:.035,resistance:.16};const frame=document.querySelector('iframe');let saved={};try{saved=JSON.parse(localStorage.getItem('nav-motion-preview')||'{}')}catch{}for(const key of Object.keys(defaults)){const input=document.getElementById(key);if(Number.isFinite(saved[key]))input.value=saved[key];input.addEventListener('input',update)}function update(){const settings={type:'motion-settings'};for(const key of Object.keys(defaults)){settings[key]=Number(document.getElementById(key).value);document.getElementById(key+'-value').textContent=key==='duration'?settings[key]+' ms':key==='bounce'?settings[key].toFixed(2):Math.round(settings[key]*100)+'%'}frame.contentWindow.postMessage(settings,location.origin);try{localStorage.setItem('nav-motion-preview',JSON.stringify(settings))}catch{}}window.addEventListener('message',event=>{if(event.origin===location.origin&&event.source===frame.contentWindow&&event.data?.type==='motion-ready')update()});frame.addEventListener('load',update);document.getElementById('reset').addEventListener('click',()=>{for(const [key,value] of Object.entries(defaults))document.getElementById(key).value=value;update()});update();